// Markdown 解析器 - 输出裸 HTML，样式由外部 CSS 主题文件负责
const marked = {
  parse: function(text) {
    if (!text) return '';

    // HTML 转义（防止用户输入的 < > & 被当成标签）
    text = text.replace(/&/g, '&amp;')
               .replace(/</g, '&lt;')
               .replace(/>/g, '&gt;');

    const lines = text.split('\n');
    const result = [];
    let i = 0;
    let inCodeBlock = false;
    let codeContent = [];

    // 递归渲染嵌套列表（支持无序/有序/任务列表，任意缩进层级）
    const parseList = (lines, startIdx, baseIndent, ordered) => {
      const html = [];
      const tag = ordered ? 'ol' : 'ul';
      html.push('<' + tag + '>');
      let idx = startIdx;

      while (idx < lines.length) {
        const raw = lines[idx];
        if (raw.trim() === '') { idx++; continue; }

        const indentMatch = raw.match(/^(\s*)/);
        const indent = indentMatch ? indentMatch[1].length : 0;

        if (indent < baseIndent) break;

        const ulMatch = raw.match(/^(\s*)[-*+]\s(.*)/);
        const olMatch = raw.match(/^(\s*)\d+\.\s(.*)/);

        if (!ulMatch && !olMatch) break;

        const itemIndent = (ulMatch || olMatch)[1].length;
        if (itemIndent < baseIndent) break;
        if (itemIndent > baseIndent) break; // 属于上一项的子列表，由递归处理

        // 任务列表检测
        const taskMatch = raw.match(/^(\s*)[-*+]\s\[([ xX])\]\s(.*)/);
        let itemContent;
        if (taskMatch) {
          const checked = taskMatch[2].toLowerCase() === 'x';
          itemContent = '<input type="checkbox"' + (checked ? ' checked' : '') + ' disabled> ' + self.parseInline(taskMatch[3]);
        } else {
          const rawContent = ulMatch ? ulMatch[2] : olMatch[2];
          itemContent = self.parseInline(rawContent);
        }

        idx++;

        // 检查下一行是否是子列表（缩进更深）
        let subHtml = '';
        if (idx < lines.length) {
          const nextRaw = lines[idx];
          if (nextRaw.trim() !== '') {
            const nextIndentMatch = nextRaw.match(/^(\s*)/);
            const nextIndent = nextIndentMatch ? nextIndentMatch[1].length : 0;
            const nextIsUl = /^\s+[-*+]\s/.test(nextRaw);
            const nextIsOl = /^\s+\d+\.\s/.test(nextRaw);
            if (nextIndent > itemIndent && (nextIsUl || nextIsOl)) {
              const subOrdered = nextIsOl && !nextIsUl;
              const [subResult, newIdx] = parseList(lines, idx, nextIndent, subOrdered);
              subHtml = subResult;
              idx = newIdx;
            }
          }
        }

        html.push('<li>' + itemContent + subHtml + '</li>');
      }

      html.push('</' + tag + '>');
      return [html.join(''), idx];
    };

    const self = this;

    while (i < lines.length) {
      const line = lines[i];

      // 代码块
      if (line.startsWith('```')) {
        if (!inCodeBlock) {
          inCodeBlock = true;
          codeContent = [];
        } else {
          inCodeBlock = false;
          const escapedCode = codeContent.join('\n')
            .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
          result.push('<pre><code>' + escapedCode + '</code></pre>');
        }
        i++;
        continue;
      }

      if (inCodeBlock) {
        codeContent.push(line);
        i++;
        continue;
      }

      // 标题
      if (line.match(/^#{1,6}\s/)) {
        const match = line.match(/^(#{1,6})\s(.+)$/);
        const level = match[1].length;
        const content = this.parseInline(match[2]);
        result.push('<h' + level + '>' + content + '</h' + level + '>');
        i++;
        continue;
      }

      // 无序列表（含任务列表，支持嵌套）
      if (line.match(/^[-*+]\s/)) {
        const [listHtml, newIdx] = parseList(lines, i, 0, false);
        result.push(listHtml);
        i = newIdx;
        continue;
      }

      // 有序列表（支持嵌套）
      if (line.match(/^\d+\.\s/)) {
        const [listHtml, newIdx] = parseList(lines, i, 0, true);
        result.push(listHtml);
        i = newIdx;
        continue;
      }

      // 表格
      if (line.match(/^\|.+\|/)) {
        const tableLines = [];
        while (i < lines.length && lines[i].match(/^\|.+\|/)) {
          tableLines.push(lines[i]);
          i++;
        }
        result.push(this.parseTable(tableLines));
        continue;
      }

      // 引用块（> 在转义后变为 &gt;）
      if (line.match(/^(&gt;|>)/)) {
        const quotes = [];
        while (i < lines.length && lines[i].match(/^(&gt;|>)/)) {
          quotes.push(lines[i].replace(/^(&gt;|>)\s*/, ''));
          i++;
        }
        result.push('<blockquote>' + this.parseInline(quotes.join(' ')) + '</blockquote>');
        continue;
      }

      // 分隔线（支持 ---, ***, ___ 三种形式）
      if (line.match(/^(\-{3,}|\*{3,}|_{3,})$/)) {
        result.push('<hr>');
        i++;
        continue;
      }

      // 空行
      if (line.trim() === '') {
        i++;
        continue;
      }

      // 普通段落
      result.push('<p>' + this.parseInline(line) + '</p>');
      i++;
    }

    return result.join('\n');
  },

  parseInline: function(text) {
    if (!text) return '';

    text = text.replace(/&amp;/g, '&')
               .replace(/&lt;/g, '<')
               .replace(/&gt;/g, '>');

    // 图片（先于链接处理，避免被链接正则误匹配）
    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1">');

    // 链接
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');

    // 粗斜体（先于粗体和斜体处理）
    text = text.replace(/\*\*\*([\s\S]+?)\*\*\*/g, '<strong><em>$1</em></strong>');

    // 粗体
    text = text.replace(/\*\*([\s\S]+?)\*\*/g, '<strong>$1</strong>');
    text = text.replace(/__([\s\S]+?)__/g, '<strong>$1</strong>');

    // 斜体
    text = text.replace(/\*([\s\S]+?)\*/g, '<em>$1</em>');
    text = text.replace(/_([\s\S]+?)_/g, '<em>$1</em>');

    // 删除线
    text = text.replace(/~~([\s\S]+?)~~/g, '<del>$1</del>');

    // 行内代码
    text = text.replace(/`([^`]+)`/g, '<code>$1</code>');

    // <u> 标签透传
    text = text.replace(/<u>([\s\S]+?)<\/u>/g, '<u>$1</u>');

    // <kbd> 标签透传
    text = text.replace(/<kbd>([\s\S]+?)<\/kbd>/g, '<kbd>$1</kbd>');

    return text;
  },

  parseTable: function(lines) {
    if (lines.length < 2) return '';

    const headers = lines[0].split('|').slice(1, -1).map(h => h.trim());
    const alignRow = lines[1];
    const alignments = alignRow.split('|').slice(1, -1).map(a => {
      a = a.trim();
      if (a.startsWith(':') && a.endsWith(':')) return 'center';
      if (a.endsWith(':')) return 'right';
      if (a.startsWith(':')) return 'left';
      return 'left';
    });

    let html = '<table>';
    html += '<thead><tr>';
    headers.forEach((h, i) => {
      html += '<th style="text-align:' + (alignments[i] || 'left') + '">' + h + '</th>';
    });
    html += '</tr></thead><tbody>';

    for (let i = 2; i < lines.length; i++) {
      const cells = lines[i].split('|').slice(1, -1).map(c => c.trim());
      html += '<tr>';
      cells.forEach((c, j) => {
        html += '<td style="text-align:' + (alignments[j] || 'left') + '">' + this.parseInline(c) + '</td>';
      });
      html += '</tr>';
    }

    html += '</tbody></table>';
    return html;
  }
};
